     1→/**
     2→ * FreeLang Nexus - 통합 Parser
     3→ * V 모드 + Python 모드 함수를 혼합하여 파싱
     4→ */
     5→
     6→import { Token, TokenType } from '../lexer/token';
     7→import * as AST from './ast';
     8→
     9→export class NexusParser {
    10→  private tokens: Token[];
    11→  private pos: number = 0;
    12→
    13→  constructor(tokens: Token[]) {
    14→    this.tokens = tokens;
    15→  }
    16→
    17→  /**
    18→   * 파싱 진입점
    19→   */
    20→  parse(): AST.Program {
    21→    const body: Array<AST.VFunction | AST.PyFunction | AST.Statement> = [];
    22→
    23→    while (!this.isAtEnd()) {
    24→      this.skipNewlines();
    25→      if (this.isAtEnd()) break;
    26→
    27→      const token = this.peek();
    28→
    29→      // @mode 마커는 스킵 (이미 렉서에서 처리됨)
    30→      if (token.type === TokenType.MODE_MARKER) {
    31→        this.advance();
    32→        continue;
    33→      }
    34→
    35→      // 탑레벨 아이템 파싱
    36→      const item = this.parseTopLevel();
    37→      if (item) {
    38→        body.push(item);
    39→      }
    40→    }
    41→
    42→    return { type: 'Program', body };
    43→  }
    44→
    45→  /**
    46→   * 탑레벨 아이템 파싱
    47→   * V 함수, Python 함수, 또는 문장
    48→   */
    49→  private parseTopLevel(): AST.VFunction | AST.PyFunction | AST.Statement | null {
    50→    const token = this.peek();
    51→
    52→    // V 모드 함수
    53→    if (token.type === TokenType.FN) {
    54→      return this.parseVFunction();
    55→    }
    56→
    57→    // Python 모드 함수
    58→    if (token.type === TokenType.DEF) {
    59→      return this.parsePyFunction();
    60→    }
    61→
    62→    // 그 외: 문장
    63→    return this.parseStatement();
    64→  }
    65→
    66→  /**
    67→   * V 함수 파싱
    68→   * fn name(params) -> type { body }
    69→   */
    70→  private parseVFunction(): AST.VFunction {
    71→    const startToken = this.consume(TokenType.FN, 'fn 키워드 필요');
    72→    const nameToken = this.consume(TokenType.IDENTIFIER, '함수명 필요');
    73→    const name = nameToken.value;
    74→
    75→    this.consume(TokenType.LPAREN, '( 필요');
    76→    const params = this.parseVParams();
    77→    this.consume(TokenType.RPAREN, ') 필요');
    78→
    79→    const returnType = this.parseReturnType();
    80→
    81→    this.consume(TokenType.LBRACE, '{ 필요');
    82→    const body = this.parseVBlock();
    83→    this.consume(TokenType.RBRACE, '} 필요');
    84→
    85→    return {
    86→      type: 'VFunction',
    87→      name,
    88→      params,
    89→      returnType,
    90→      body,
    91→      mode: 'v',
    92→      line: startToken.line,
    93→      column: startToken.column,
    94→    };
    95→  }
    96→
    97→  /**
    98→   * Python 함수 파싱
    99→   * def name(params): INDENT body DEDENT
   100→   */
   101→  private parsePyFunction(): AST.PyFunction {
   102→    const startToken = this.consume(TokenType.DEF, 'def 키워드 필요');
   103→    const nameToken = this.consume(TokenType.IDENTIFIER, '함수명 필요');
   104→    const name = nameToken.value;
   105→
   106→    this.consume(TokenType.LPAREN, '( 필요');
   107→    const params = this.parsePyParams();
   108→    this.consume(TokenType.RPAREN, ') 필요');
   109→
   110→    const returnType = this.parseReturnType();
   111→
   112→    this.consume(TokenType.COLON, ': 필요');
   113→    this.skipNewlines();
   114→
   115→    const body = this.parsePyBlock();
   116→
   117→    return {
   118→      type: 'PyFunction',
   119→      name,
   120→      params,
   121→      returnType,
   122→      body,
   123→      mode: 'python',
   124→      line: startToken.line,
   125→      column: startToken.column,
   126→    };
   127→  }
   128→
   129→  /**
   130→   * V 함수 파라미터 파싱
   131→   * (x: i64, y: i64)
   132→   */
   133→  private parseVParams(): AST.Parameter[] {
   134→    const params: AST.Parameter[] = [];
   135→
   136→    while (!this.check(TokenType.RPAREN) && !this.isAtEnd()) {
   137→      const nameToken = this.consume(TokenType.IDENTIFIER, '파라미터명 필요');
   138→      this.consume(TokenType.COLON, ': 필요');
   139→      const typeToken = this.peek();
   140→      const typeAnnotation = this.parseType();
   141→
   142→      params.push({
   143→        name: nameToken.value,
   144→        typeAnnotation,
   145→        line: nameToken.line,
   146→        column: nameToken.column,
   147→      });
   148→
   149→      if (!this.check(TokenType.RPAREN)) {
   150→        this.consume(TokenType.COMMA, ', 필요');
   151→      }
   152→    }
   153→
   154→    return params;
   155→  }
   156→
   157→  /**
   158→   * Python 함수 파라미터 파싱
   159→   * (x, y) 또는 (x: int, y: int)
   160→   */
   161→  private parsePyParams(): AST.Parameter[] {
   162→    const params: AST.Parameter[] = [];
   163→
   164→    while (!this.check(TokenType.RPAREN) && !this.isAtEnd()) {
   165→      const nameToken = this.consume(TokenType.IDENTIFIER, '파라미터명 필요');
   166→      let typeAnnotation: string | undefined;
   167→
   168→      // 타입 어노테이션 (선택)
   169→      if (this.check(TokenType.COLON)) {
   170→        this.advance();
   171→        typeAnnotation = this.parseType();
   172→      }
   173→
   174→      params.push({
   175→        name: nameToken.value,
   176→        typeAnnotation,
   177→        line: nameToken.line,
   178→        column: nameToken.column,
   179→      });
   180→
   181→      if (!this.check(TokenType.RPAREN)) {
   182→        this.consume(TokenType.COMMA, ', 필요');
   183→      }
   184→    }
   185→
   186→    return params;
   187→  }
   188→
   189→  /**
   190→   * 반환 타입 파싱
   191→   * -> i64 (선택)
   192→   */
   193→  private parseReturnType(): string | undefined {
   194→    if (this.match(TokenType.ARROW)) {
   195→      return this.parseType();
   196→    }
   197→    return undefined;
   198→  }
   199→
   200→  /**
   201→   * 타입 파싱
   202→   * i64, string, bool 등
   203→   */
   204→  private parseType(): string {
   205→    const token = this.peek();
   206→
   207→    // 기본 타입
   208→    if (
   209→      token.type === TokenType.I64 ||
   210→      token.type === TokenType.I32 ||
   211→      token.type === TokenType.F64 ||
   212→      token.type === TokenType.BOOL ||
   213→      token.type === TokenType.STRING ||
   214→      token.type === TokenType.IDENTIFIER
   215→    ) {
   216→      return this.advance().value;
   217→    }
   218→
   219→    throw new Error(`타입 필요 at line ${token.line}`);
   220→  }
   221→
   222→  /**
   223→   * V 블록 파싱
   224→   * { statements }
   225→   */
   226→  private parseVBlock(): AST.Statement[] {
   227→    const statements: AST.Statement[] = [];
   228→
   229→    while (!this.check(TokenType.RBRACE) && !this.isAtEnd()) {
   230→      this.skipNewlines();
   231→
   232→      if (this.check(TokenType.RBRACE)) break;
   233→
   234→      const stmt = this.parseStatement();
   235→      if (stmt) {
   236→        statements.push(stmt);
   237→      }
   238→
   239→      this.skipNewlines();
   240→    }
   241→
   242→    return statements;
   243→  }
   244→
   245→  /**
   246→   * Python 블록 파싱
   247→   * INDENT statements DEDENT
   248→   */
   249→  private parsePyBlock(): AST.Statement[] {
   250→    const statements: AST.Statement[] = [];
   251→
   252→    this.consume(TokenType.INDENT, 'INDENT 필요');
   253→
   254→    while (!this.check(TokenType.DEDENT) && !this.isAtEnd()) {
   255→      this.skipNewlines();
   256→
   257→      if (this.check(TokenType.DEDENT) || this.isAtEnd()) break;
   258→
   259→      const stmt = this.parseStatement();
   260→      if (stmt) {
   261→        statements.push(stmt);
   262→      }
   263→
   264→      this.skipNewlines();
   265→    }
   266→
   267→    // DEDENT 또는 EOF 모두 허용 (파일 끝에서 DEDENT가 항상 생성되지 않을 수 있음)
   268→    if (this.check(TokenType.DEDENT)) {
   269→      this.advance();
   270→    }
   271→
   272→    return statements;
   273→  }
   274→
   275→  /**
   276→   * 문장 파싱
   277→   */
   278→  private parseStatement(): AST.Statement {
   279→    const token = this.peek();
   280→
   281→    // return 문장
   282→    if (token.type === TokenType.RETURN) {
   283→      return this.parseReturnStatement();
   284→    }
   285→
   286→    // if 문장
   287→    if (token.type === TokenType.IF) {
   288→      return this.parseIfStatement();
   289→    }
   290→
   291→    // while 루프
   292→    if (token.type === TokenType.WHILE) {
   293→      return this.parseWhileStatement();
   294→    }
   295→
   296→    // for 루프
   297→    if (token.type === TokenType.FOR) {
   298→      return this.parseForStatement();
   299→    }
   300→
   301→    // pass 문장 (Python)
   302→    if (token.type === TokenType.PASS) {
   303→      const passToken = this.advance();
   304→      return {
   305→        type: 'ExprStatement',
   306→        expression: {
   307→          type: 'Identifier',
   308→          name: 'pass',
   309→          line: passToken.line,
   310→          column: passToken.column,
   311→          mode: passToken.mode,
   312→        },
   313→        line: passToken.line,
   314→        column: passToken.column,
   315→        mode: passToken.mode,
   316→      };
   317→    }
   318→
   319→    // let 또는 식별자 (할당 가능성)
   320→    if (token.type === TokenType.LET || token.type === TokenType.IDENTIFIER) {
   321→      return this.parseAssignOrExpr();
   322→    }
   323→
   324→    // 기본값: 표현식 문장
   325→    const expr = this.parseExpression();
   326→    const startToken = this.peek();
   327→    return {
   328→      type: 'ExprStatement',
   329→      expression: expr,
   330→      line: startToken.line,
   331→      column: startToken.column,
   332→      mode: startToken.mode,
   333→    };
   334→  }
   335→
   336→  /**
   337→   * Return 문장 파싱
   338→   */
   339→  private parseReturnStatement(): AST.ReturnStatement {
   340→    const startToken = this.consume(TokenType.RETURN, 'return 필요');
   341→    let value: AST.Expression | undefined;
   342→
   343→    // 반환값이 있으면 파싱
   344→    if (!this.check(TokenType.NEWLINE) && !this.check(TokenType.DEDENT) && !this.check(TokenType.RBRACE)) {
   345→      value = this.parseExpression();
   346→    }
   347→
   348→    return {
   349→      type: 'Return',
   350→      value,
   351→      line: startToken.line,
   352→      column: startToken.column,
   353→      mode: startToken.mode,
   354→    };
   355→  }
   356→
   357→  /**
   358→   * 할당 또는 표현식 파싱
   359→   */
   360→  private parseAssignOrExpr(): AST.Statement {
   361→    const startToken = this.peek();
   362→
   363→    // let x = value
   364→    if (startToken.type === TokenType.LET) {
   365→      this.advance();
   366→      const nameToken = this.consume(TokenType.IDENTIFIER, '변수명 필요');
   367→      this.consume(TokenType.EQUAL, '= 필요');
   368→      const value = this.parseExpression();
   369→
   370→      return {
   371→        type: 'Assign',
   372→        name: nameToken.value,
   373→        value,
   374→        line: startToken.line,
   375→        column: startToken.column,
   376→        mode: startToken.mode,
   377→      };
   378→    }
   379→
   380→    // x = value 또는 함수호출 등
   381→    if (startToken.type === TokenType.IDENTIFIER) {
   382→      const nameToken = this.peek();
   383→      const name = nameToken.value;
   384→      this.advance();
   385→
   386→      if (this.check(TokenType.EQUAL)) {
   387→        this.advance();
   388→        const value = this.parseExpression();
   389→
   390→        return {
   391→          type: 'Assign',
   392→          name,
   393→          value,
   394→          line: startToken.line,
   395→          column: startToken.column,
   396→          mode: startToken.mode,
   397→        };
   398→      }
   399→
   400→      // 아니면 전체 표현식으로 다시 파싱 (함수호출 등 포함)
   401→      // pos를 한 칸 뒤로 이동하여 식별자부터 다시 파싱
   402→      this.pos--;
   403→      const expr = this.parseExpression();
   404→
   405→      return {
   406→        type: 'ExprStatement',
   407→        expression: expr,
   408→        line: startToken.line,
   409→        column: startToken.column,
   410→        mode: startToken.mode,
   411→      };
   412→    }
   413→
   414→    throw new Error(`예상치 못한 토큰 at line ${startToken.line}`);
   415→  }
   416→
   417→  /**
   418→   * If 문장 파싱
   419→   * if condition { body } [else { body }]
   420→   */
   421→  private parseIfStatement(): AST.IfStatement {
   422→    const startToken = this.consume(TokenType.IF, 'if 키워드 필요');
   423→    const condition = this.parseExpression();
   424→    this.consume(TokenType.LBRACE, '{ 필요');
   425→    const thenBranch = this.parseVBlock();
   426→    this.consume(TokenType.RBRACE, '} 필요');
   427→
   428→    let elseBranch: AST.Statement[] | undefined;
   429→    if (this.match(TokenType.ELSE)) {
   430→      this.consume(TokenType.LBRACE, '{ 필요');
   431→      elseBranch = this.parseVBlock();
   432→      this.consume(TokenType.RBRACE, '} 필요');
   433→    }
   434→
   435→    return {
   436→      type: 'IfStatement',
   437→      condition,
   438→      thenBranch,
   439→      elseBranch,
   440→      line: startToken.line,
   441→      column: startToken.column,
   442→      mode: startToken.mode,
   443→    };
   444→  }
   445→
   446→  /**
   447→   * While 루프 파싱
   448→   * while condition { body }
   449→   */
   450→  private parseWhileStatement(): AST.WhileStatement {
   451→    const startToken = this.consume(TokenType.WHILE, 'while 키워드 필요');
   452→    const condition = this.parseExpression();
   453→    this.consume(TokenType.LBRACE, '{ 필요');
   454→    const body = this.parseVBlock();
   455→    this.consume(TokenType.RBRACE, '} 필요');
   456→
   457→    return {
   458→      type: 'WhileStatement',
   459→      condition,
   460→      body,
   461→      line: startToken.line,
   462→      column: startToken.column,
   463→      mode: startToken.mode,
   464→    };
   465→  }
   466→
   467→  /**
   468→   * For-In 루프 파싱
   469→   * for <variable> in <iterable> { <body> }
   470→   */
   471→  private parseForStatement(): AST.ForStatement {
   472→    const startToken = this.consume(TokenType.FOR, 'for 키워드 필요');
   473→    const varToken = this.consume(TokenType.IDENTIFIER, '루프 변수명 필요');
   474→    this.consume(TokenType.IN, 'in 키워드 필요');
   475→    const iterable = this.parseExpression();
   476→    this.consume(TokenType.LBRACE, '{ 필요');
   477→    const body = this.parseVBlock();
   478→    this.consume(TokenType.RBRACE, '} 필요');
   479→
   480→    return {
   481→      type: 'ForStatement',
   482→      variable: varToken.value,
   483→      iterable,
   484→      body,
   485→      line: startToken.line,
   486→      column: startToken.column,
   487→      mode: startToken.mode,
   488→    };
   489→  }
   490→
   491→  /**
   492→   * 표현식 파싱
   493→   * 간단한 구현: 곱셈/나눗셈 → 덧셈/뺄셈 → 비교/논리
   494→   */
   495→  private parseExpression(): AST.Expression {
   496→    return this.parseLogicalOr();
   497→  }
   498→
   499→  /**
   500→   * 논리 OR 파싱: ||
   501→   */
   502→  private parseLogicalOr(): AST.Expression {
   503→    let expr = this.parseLogicalAnd();
   504→
   505→    while (this.match(TokenType.OR)) {
   506→      const operator = this.previous().value;
   507→      const right = this.parseLogicalAnd();
   508→      const token = this.previous();
   509→      expr = {
   510→        type: 'BinaryExpr',
   511→        left: expr,
   512→        operator,
   513→        right,
   514→        line: token.line,
   515→        column: token.column,
   516→        mode: token.mode,
   517→      };
   518→    }
   519→
   520→    return expr;
   521→  }
   522→
   523→  /**
   524→   * 논리 AND 파싱: &&
   525→   */
   526→  private parseLogicalAnd(): AST.Expression {
   527→    let expr = this.parseEquality();
   528→
   529→    while (this.match(TokenType.AND)) {
   530→      const operator = this.previous().value;
   531→      const right = this.parseEquality();
   532→      const token = this.previous();
   533→      expr = {
   534→        type: 'BinaryExpr',
   535→        left: expr,
   536→        operator,
   537→        right,
   538→        line: token.line,
   539→        column: token.column,
   540→        mode: token.mode,
   541→      };
   542→    }
   543→
   544→    return expr;
   545→  }
   546→
   547→  /**
   548→   * 등호/부등호 파싱: ==, !=
   549→   */
   550→  private parseEquality(): AST.Expression {
   551→    let expr = this.parseComparison();
   552→
   553→    while (this.match(TokenType.EQ, TokenType.NE)) {
   554→      const operator = this.previous().value;
   555→      const right = this.parseComparison();
   556→      const token = this.previous();
   557→      expr = {
   558→        type: 'BinaryExpr',
   559→        left: expr,
   560→        operator,
   561→        right,
   562→        line: token.line,
   563→        column: token.column,
   564→        mode: token.mode,
   565→      };
   566→    }
   567→
   568→    return expr;
   569→  }
   570→
   571→  /**
   572→   * 비교 파싱: <, >, <=, >=
   573→   */
   574→  private parseComparison(): AST.Expression {
   575→    let expr = this.parseAddition();
   576→
   577→    while (this.match(TokenType.LT, TokenType.GT, TokenType.LE, TokenType.GE)) {
   578→      const operator = this.previous().value;
   579→      const right = this.parseAddition();
   580→      const token = this.previous();
   581→      expr = {
   582→        type: 'BinaryExpr',
   583→        left: expr,
   584→        operator,
   585→        right,
   586→        line: token.line,
   587→        column: token.column,
   588→        mode: token.mode,
   589→      };
   590→    }
   591→
   592→    return expr;
   593→  }
   594→
   595→  /**
   596→   * 덧셈/뺄셈 파싱
   597→   */
   598→  private parseAddition(): AST.Expression {
   599→    let expr = this.parseMultiplication();
   600→
   601→    while (this.match(TokenType.PLUS, TokenType.MINUS)) {
   602→      const operator = this.previous().value;
   603→      const right = this.parseMultiplication();
   604→      const token = this.previous();
   605→      expr = {
   606→        type: 'BinaryExpr',
   607→        left: expr,
   608→        operator,
   609→        right,
   610→        line: token.line,
   611→        column: token.column,
   612→        mode: token.mode,
   613→      };
   614→    }
   615→
   616→    return expr;
   617→  }
   618→
   619→  /**
   620→   * 곱셈/나눗셈 파싱
   621→   */
   622→  private parseMultiplication(): AST.Expression {
   623→    let expr = this.parseUnary();
   624→
   625→    while (this.match(TokenType.STAR, TokenType.SLASH)) {
   626→      const operator = this.previous().value;
   627→      const right = this.parseUnary();
   628→      const token = this.previous();
   629→      expr = {
   630→        type: 'BinaryExpr',
   631→        left: expr,
   632→        operator,
   633→        right,
   634→        line: token.line,
   635→        column: token.column,
   636→        mode: token.mode,
   637→      };
   638→    }
   639→
   640→    return expr;
   641→  }
   642→
   643→  /**
   644→   * 단항 연산 파싱
   645→   */
   646→  private parseUnary(): AST.Expression {
   647→    // TODO: 단항 연산자 (-, !, ~) 처리 가능
   648→    return this.parsePostfix();
   649→  }
   650→
   651→  /**
   652→   * 후위 연산 파싱 (함수 호출, 배열 접근)
   653→   */
   654→  private parsePostfix(): AST.Expression {
   655→    let expr = this.parsePrimary();
   656→
   657→    while (true) {
   658→      // 함수 호출: foo()
   659→      if (this.match(TokenType.LPAREN)) {
   660→        const args = this.parseArguments();
   661→        this.consume(TokenType.RPAREN, ') 필요');
   662→
   663→        const token = this.previous();
   664→        expr = {
   665→          type: 'Call',
   666→          callee: expr,
   667→          args,
   668→          line: token.line,
   669→          column: token.column,
   670→          mode: token.mode,
   671→        };
   672→      }
   673→      // 배열 인덱싱: arr[0]
   674→      else if (this.match(TokenType.LBRACKET)) {
   675→        const index = this.parseExpression();
   676→        const token = this.consume(TokenType.RBRACKET, '] 필요');
   677→
   678→        expr = {
   679→          type: 'ArrayAccess',
   680→          object: expr,
   681→          index,
   682→          line: token.line,
   683→          column: token.column,
   684→          mode: token.mode,
   685→        };
   686→      }
   687→      // 멤버 접근: obj.property
   688→      else if (this.match(TokenType.DOT)) {
   689→        const propToken = this.consume(TokenType.IDENTIFIER, '프로퍼티명 필요');
   690→        const token = this.previous();
   691→
   692→        expr = {
   693→          type: 'MemberAccess',
   694→          object: expr,
   695→          property: propToken.value,
   696→          line: token.line,
   697→          column: token.column,
   698→          mode: token.mode,
   699→        };
   700→      } else {
   701→        break;
   702→      }
   703→    }
   704→
   705→    return expr;
   706→  }
   707→
   708→  /**
   709→   * 기본 표현식 파싱 (리터럴, 식별자 등)
   710→   */
   711→  private parsePrimary(): AST.Expression {
   712→    const token = this.peek();
   713→
   714→    // 숫자
   715→    if (token.type === TokenType.NUMBER) {
   716→      this.advance();
   717→      return {
   718→        type: 'Number',
   719→        value: token.value,
   720→        line: token.line,
   721→        column: token.column,
   722→        mode: token.mode,
   723→      };
   724→    }
   725→
   726→    // 문자열
   727→    if (token.type === TokenType.STRING) {
   728→      this.advance();
   729→      return {
   730→        type: 'String',
   731→        value: token.value,
   732→        line: token.line,
   733→        column: token.column,
   734→        mode: token.mode,
   735→      };
   736→    }
   737→
   738→    // true, false
   739→    if (token.type === TokenType.TRUE || token.type === TokenType.FALSE) {
   740→      this.advance();
   741→      return {
   742→        type: 'Number',
   743→        value: token.type === TokenType.TRUE ? 1 : 0,
   744→        line: token.line,
   745→        column: token.column,
   746→        mode: token.mode,
   747→      };
   748→    }
   749→
   750→    // 배열 리터럴: [1, 2, 3]
   751→    if (token.type === TokenType.LBRACKET) {
   752→      return this.parseArrayLiteral();
   753→    }
   754→
   755→    // 식별자
   756→    if (token.type === TokenType.IDENTIFIER) {
   757→      this.advance();
   758→      return {
   759→        type: 'Identifier',
   760→        name: token.value,
   761→        line: token.line,
   762→        column: token.column,
   763→        mode: token.mode,
   764→      };
   765→    }
   766→
   767→    // 괄호 식
   768→    if (this.match(TokenType.LPAREN)) {
   769→      const expr = this.parseExpression();
   770→      this.consume(TokenType.RPAREN, ') 필요');
   771→      return expr;
   772→    }
   773→
   774→    throw new Error(`예상치 못한 토큰: ${token.value} at line ${token.line}`);
   775→  }
   776→
   777→  /**
   778→   * 배열 리터럴 파싱
   779→   * [1, 2, 3], [], [a+b, c*d], [1, 2,] (trailing comma 지원)
   780→   */
   781→  private parseArrayLiteral(): AST.ArrayLiteral {
   782→    const startToken = this.consume(TokenType.LBRACKET, '[');
   783→    const elements: AST.Expression[] = [];
   784→
   785→    // 빈 배열 또는 요소들
   786→    while (!this.check(TokenType.RBRACKET) && !this.isAtEnd()) {
   787→      elements.push(this.parseExpression());
   788→
   789→      // 쉼표가 있으면 계속, 없으면 종료
   790→      if (!this.match(TokenType.COMMA)) {
   791→        break;
   792→      }
   793→
   794→      // trailing comma: 쉼표 뒤에 ] 가 있으면 즉시 종료
   795→      if (this.check(TokenType.RBRACKET)) {
   796→        break;
   797→      }
   798→    }
   799→
   800→    const endToken = this.consume(TokenType.RBRACKET, '] 필요');
   801→
   802→    return {
   803→      type: 'Array',
   804→      elements,
   805→      line: startToken.line,
   806→      column: startToken.column,
   807→      mode: startToken.mode,
   808→    };
   809→  }
   810→
   811→  /**
   812→   * 함수 호출 인자 파싱
   813→   */
   814→  private parseArguments(): AST.Expression[] {
   815→    const args: AST.Expression[] = [];
   816→
   817→    if (!this.check(TokenType.RPAREN)) {
   818→      do {
   819→        args.push(this.parseExpression());
   820→      } while (this.match(TokenType.COMMA));
   821→    }
   822→
   823→    return args;
   824→  }
   825→
   826→  // ========== 헬퍼 메서드 ==========
   827→
   828→  private peek(): Token {
   829→    if (this.pos >= this.tokens.length) {
   830→      return this.tokens[this.tokens.length - 1]; // EOF 토큰
   831→    }
   832→    return this.tokens[this.pos];
   833→  }
   834→
   835→  private advance(): Token {
   836→    if (!this.isAtEnd()) {
   837→      this.pos++;
   838→    }
   839→    return this.previous();
   840→  }
   841→
   842→  private previous(): Token {
   843→    return this.tokens[this.pos - 1];
   844→  }
   845→
   846→  private isAtEnd(): boolean {
   847→    return this.peek().type === TokenType.EOF;
   848→  }
   849→
   850→  private check(type: TokenType): boolean {
   851→    if (this.isAtEnd()) return false;
   852→    return this.peek().type === type;
   853→  }
   854→
   855→  private match(...types: TokenType[]): boolean {
   856→    for (const type of types) {
   857→      if (this.check(type)) {
   858→        this.advance();
   859→        return true;
   860→      }
   861→    }
   862→    return false;
   863→  }
   864→
   865→  private consume(type: TokenType, message: string): Token {
   866→    if (this.check(type)) return this.advance();
   867→
   868→    const token = this.peek();
   869→    throw new Error(`${message} at line ${token.line}, got ${token.value}`);
   870→  }
   871→
   872→  private skipNewlines(): void {
   873→    while (this.match(TokenType.NEWLINE)) {
   874→      // 계속
   875→    }
   876→  }
   877→}
