     1→/**
     2→ * FreeLang Nexus - 코드 생성기
     3→ * AST → C 코드 (V 모드) + Python 코드 (Python 모드)
     4→ */
     5→
     6→import * as AST from '../parser/ast';
     7→
     8→export interface CodegenResult {
     9→  c: string;       // V 모드 함수들 → C 코드
    10→  python: string;  // Python 모드 함수들 → Python 코드
    11→  mixed: string;   // 두 코드 주석으로 구분 (디버그용)
    12→}
    13→
    14→export class NexusCodegen {
    15→  private cLines: string[] = [];
    16→  private pyLines: string[] = [];
    17→  private indentLevel: number = 0;
    18→
    19→  /**
    20→   * V 모드 내장 함수 처리
    21→   */
    22→  private readonly V_BUILTINS = new Set(['println', 'print', 'len', 'to_string', 'int_cast']);
    23→
    24→  /**
    25→   * 프로그램 전체 코드 생성
    26→   */
    27→  generate(program: AST.Program): CodegenResult {
    28→    // @mode 마커는 무시하고 함수/문장만 처리
    29→    for (const item of program.body) {
    30→      const fnItem = item as any;
    31→      if (fnItem.type === 'VFunction') {
    32→        this.genVFunction(fnItem as AST.VFunction);
    33→      } else if (fnItem.type === 'PyFunction') {
    34→        this.genPyFunction(fnItem as AST.PyFunction);
    35→      } else if (fnItem.type === 'Return' || fnItem.type === 'Assign' || fnItem.type === 'ExprStatement') {
    36→        // 탑레벨 문장은 V 모드(C)로 처리
    37→        this.genVStatement(fnItem as AST.Statement);
    38→      }
    39→    }
    40→
    41→    const c = this.cLines.join('\n');
    42→    const python = this.pyLines.join('\n');
    43→
    44→    // mixed: 두 언어 코드를 주석으로 구분해서 출력 (확인용)
    45→    const mixed =
    46→      c && python
    47→        ? `/* ===== V (C) ===== */\n${c}\n\n/* ===== Python ===== */\n# (Not valid C, just for reference)\n${python}`
    48→        : c || python;
    49→
    50→    return { c, python, mixed };
    51→  }
    52→
    53→  /**
    54→   * 실행 가능한 프로그램 생성
    55→   * C에는 #include + main() 추가, Python에는 if __name__ 추가
    56→   */
    57→  generateProgram(program: AST.Program): CodegenResult {
    58→    const base = this.generate(program);
    59→
    60→    // C 코드에 헤더 + main() wrapping 추가
    61→    const cWithMain = base.c
    62→      ? `#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n\n${base.c}\nint main() {\n    return 0;\n}\n`
    63→      : '';
    64→
    65→    // Python 코드에 main 블록 추가
    66→    const pyWithMain = base.python
    67→      ? `${base.python}\n\nif __name__ == '__main__':\n    pass\n`
    68→      : '';
    69→
    70→    return {
    71→      c: cWithMain,
    72→      python: pyWithMain,
    73→      mixed: base.mixed,
    74→    };
    75→  }
    76→
    77→  /**
    78→   * V 함수 → C 함수
    79→   * fn add(x: i64, y: i64) -> i64 { return x + y }
    80→   * →
    81→   * long long add(long long x, long long y) { return x + y; }
    82→   */
    83→  private genVFunction(fn: AST.VFunction): void {
    84→    // 반환타입
    85→    const returnType = this.mapVType(fn.returnType || 'void');
    86→
    87→    // 파라미터 리스트
    88→    const paramList = fn.params.map((p) => `${this.mapVType(p.typeAnnotation || 'void')} ${p.name}`).join(', ');
    89→
    90→    // 함수 시그니처
    91→    this.writeC(`${returnType} ${fn.name}(${paramList}) {`);
    92→
    93→    // 함수 본문
    94→    this.indentLevel++;
    95→    for (const stmt of fn.body) {
    96→      this.genVStatement(stmt);
    97→    }
    98→    this.indentLevel--;
    99→
   100→    this.writeC('}');
   101→    this.writeC(''); // 빈 줄
   102→  }
   103→
   104→  /**
   105→   * Python 함수 → Python 함수
   106→   * def slow(items): return items
   107→   * →
   108→   * def slow(items):
   109→   *     return items
   110→   */
   111→  private genPyFunction(fn: AST.PyFunction): void {
   112→    // 파라미터 리스트
   113→    const paramList = fn.params.map((p) => p.name).join(', ');
   114→
   115→    // 함수 정의
   116→    this.writePy(`def ${fn.name}(${paramList}):`);
   117→
   118→    // 함수 본문 (들여쓰기 필요)
   119→    this.indentLevel++;
   120→    for (const stmt of fn.body) {
   121→      this.genPyStatement(stmt);
   122→    }
   123→    this.indentLevel--;
   124→
   125→    this.writePy(''); // 빈 줄
   126→  }
   127→
   128→  /**
   129→   * V 문장 생성 (C 코드용)
   130→   */
   131→  private genVStatement(stmt: AST.Statement): void {
   132→    const s = stmt as any;
   133→
   134→    if (s.type === 'Return') {
   135→      const returnStmt = s as AST.ReturnStatement;
   136→      if (returnStmt.value) {
   137→        const expr = this.genVExpression(returnStmt.value);
   138→        this.writeC(`${this.indent()}return ${expr};`);
   139→      } else {
   140→        this.writeC(`${this.indent()}return;`);
   141→      }
   142→    } else if (s.type === 'Assign') {
   143→      const assignStmt = s as AST.AssignStatement;
   144→      const expr = this.genVExpression(assignStmt.value);
   145→      // 값의 타입에 따라 C 타입 결정
   146→      const value = assignStmt.value as any;
   147→      let cType = 'long long'; // 기본값
   148→      if (value.type === 'String') {
   149→        cType = 'char*'; // 문자열 리터럴
   150→      }
   151→      this.writeC(`${this.indent()}${cType} ${assignStmt.name} = ${expr};`);
   152→    } else if (s.type === 'ExprStatement') {
   153→      const exprStmt = s as AST.ExprStatement;
   154→      const expr = this.genVExpression(exprStmt.expression);
   155→      this.writeC(`${this.indent()}${expr};`);
   156→    } else if (s.type === 'IfStatement') {
   157→      const ifStmt = s as AST.IfStatement;
   158→      const cond = this.genVExpression(ifStmt.condition);
   159→      this.writeC(`${this.indent()}if (${cond}) {`);
   160→      this.indentLevel++;
   161→      for (const stmt of ifStmt.thenBranch) {
   162→        this.genVStatement(stmt);
   163→      }
   164→      this.indentLevel--;
   165→      this.writeC(`${this.indent()}}`);
   166→      if (ifStmt.elseBranch) {
   167→        this.writeC(`${this.indent()}else {`);
   168→        this.indentLevel++;
   169→        for (const stmt of ifStmt.elseBranch) {
   170→          this.genVStatement(stmt);
   171→        }
   172→        this.indentLevel--;
   173→        this.writeC(`${this.indent()}}`);
   174→      }
   175→    } else if (s.type === 'WhileStatement') {
   176→      const whileStmt = s as AST.WhileStatement;
   177→      const cond = this.genVExpression(whileStmt.condition);
   178→      this.writeC(`${this.indent()}while (${cond}) {`);
   179→      this.indentLevel++;
   180→      for (const stmt of whileStmt.body) {
   181→        this.genVStatement(stmt);
   182→      }
   183→      this.indentLevel--;
   184→      this.writeC(`${this.indent()}}`);
   185→    } else if (s.type === 'ForStatement') {
   186→      const forStmt = s as AST.ForStatement;
   187→      const iterExpr = forStmt.iterable as any;
   188→
   189→      // range(n) CallExpr 케이스
   190→      if (iterExpr.type === 'Call') {
   191→        const callee = iterExpr.callee as any;
   192→        const calleeName = callee.type === 'Identifier' ? callee.name : '';
   193→        if (calleeName === 'range' && iterExpr.args.length === 1) {
   194→          const limit = this.genVExpression(iterExpr.args[0]);
   195→          this.writeC(`${this.indent()}for (long long ${forStmt.variable} = 0; ${forStmt.variable} < ${limit}; ${forStmt.variable}++) {`);
   196→        } else {
   197→          // range가 아닌 일반 CallExpr - 기본 처리
   198→          const iterStr = this.genVExpression(forStmt.iterable);
   199→          this.writeC(`${this.indent()}for (long long ${forStmt.variable} = 0; ${forStmt.variable} < ${iterStr}; ${forStmt.variable}++) {`);
   200→        }
   201→      } else {
   202→        // 배열/변수 케이스: sizeof 패턴
   203→        const iterStr = this.genVExpression(forStmt.iterable);
   204→        this.writeC(`${this.indent()}for (long long ${forStmt.variable} = 0; ${forStmt.variable} < sizeof(${iterStr})/sizeof(${iterStr}[0]); ${forStmt.variable}++) {`);
   205→      }
   206→
   207→      this.indentLevel++;
   208→      for (const stmt of forStmt.body) {
   209→        this.genVStatement(stmt);
   210→      }
   211→      this.indentLevel--;
   212→      this.writeC(`${this.indent()}}`);
   213→    }
   214→  }
   215→
   216→  /**
   217→   * Python 문장 생성 (Python 코드용)
   218→   */
   219→  private genPyStatement(stmt: AST.Statement): void {
   220→    const s = stmt as any;
   221→    const indentStr = this.indent();
   222→
   223→    if (s.type === 'Return') {
   224→      const returnStmt = s as AST.ReturnStatement;
   225→      if (returnStmt.value) {
   226→        const expr = this.genPyExpression(returnStmt.value);
   227→        this.writePy(`${indentStr}return ${expr}`);
   228→      } else {
   229→        this.writePy(`${indentStr}return`);
   230→      }
   231→    } else if (s.type === 'Assign') {
   232→      const assignStmt = s as AST.AssignStatement;
   233→      const expr = this.genPyExpression(assignStmt.value);
   234→      this.writePy(`${indentStr}${assignStmt.name} = ${expr}`);
   235→    } else if (s.type === 'ExprStatement') {
   236→      const exprStmt = s as AST.ExprStatement;
   237→      const expr = this.genPyExpression(exprStmt.expression);
   238→      this.writePy(`${indentStr}${expr}`);
   239→    } else if (s.type === 'WhileStatement') {
   240→      const whileStmt = s as AST.WhileStatement;
   241→      const cond = this.genPyExpression(whileStmt.condition);
   242→      this.writePy(`${indentStr}while ${cond}:`);
   243→      this.indentLevel++;
   244→      for (const stmt of whileStmt.body) {
   245→        this.genPyStatement(stmt);
   246→      }
   247→      this.indentLevel--;
   248→    } else if (s.type === 'ForStatement') {
   249→      const forStmt = s as AST.ForStatement;
   250→      const iter = this.genPyExpression(forStmt.iterable);
   251→      this.writePy(`${indentStr}for ${forStmt.variable} in ${iter}:`);
   252→      this.indentLevel++;
   253→      for (const stmt of forStmt.body) {
   254→        this.genPyStatement(stmt);
   255→      }
   256→      this.indentLevel--;
   257→    }
   258→  }
   259→
   260→  /**
   261→   * V 표현식 생성 (C 코드용)
   262→   */
   263→  private genVExpression(expr: AST.Expression): string {
   264→    const e = expr as any;
   265→
   266→    if (e.type === 'Number') {
   267→      return (e as AST.NumberLiteral).value.toString();
   268→    }
   269→
   270→    if (e.type === 'String') {
   271→      // StringLiteral.value는 이미 따옴표를 포함 ("text" 형태)
   272→      return (e as AST.StringLiteral).value;
   273→    }
   274→
   275→    if (e.type === 'Identifier') {
   276→      return (e as AST.Identifier).name;
   277→    }
   278→
   279→    if (e.type === 'BinaryExpr') {
   280→      const binExpr = e as AST.BinaryExpr;
   281→      const left = this.genVExpression(binExpr.left);
   282→      const right = this.genVExpression(binExpr.right);
   283→      return `${left} ${binExpr.operator} ${right}`;
   284→    }
   285→
   286→    if (e.type === 'Array') {
   287→      const arrayLit = e as AST.ArrayLiteral;
   288→      const elements = arrayLit.elements.map((el) => this.genVExpression(el)).join(', ');
   289→      return `{${elements}}`;
   290→    }
   291→
   292→    if (e.type === 'ArrayAccess') {
   293→      const arrayAccess = e as AST.ArrayAccess;
   294→      const obj = this.genVExpression(arrayAccess.object);
   295→      const idx = this.genVExpression(arrayAccess.index);
   296→      return `${obj}[${idx}]`;
   297→    }
   298→
   299→    if (e.type === 'Call') {
   300→      const callExpr = e as AST.CallExpr;
   301→
   302→      // callee가 Identifier인 경우 함수명 추출
   303→      let calleeStr: string | null = null;
   304→      if (typeof callExpr.callee === 'string') {
   305→        calleeStr = callExpr.callee;
   306→      } else {
   307→        const calleeExpr = callExpr.callee as any;
   308→        if (calleeExpr.type === 'Identifier') {
   309→          calleeStr = calleeExpr.name;
   310→        }
   311→      }
   312→
   313→      // V 내장 함수 처리
   314→      if (calleeStr && this.V_BUILTINS.has(calleeStr)) {
   315→        return this.genVBuiltinCall(calleeStr, callExpr.args);
   316→      }
   317→
   318→      // 일반 함수 호출
   319→      const callee = typeof callExpr.callee === 'string' ? callExpr.callee : this.genVExpression(callExpr.callee);
   320→      const args = callExpr.args.map((arg) => this.genVExpression(arg)).join(', ');
   321→      return `${callee}(${args})`;
   322→    }
   323→
   324→    if (e.type === 'MemberAccess') {
   325→      const ma = e as AST.MemberAccess;
   326→      const obj = this.genVExpression(ma.object);
   327→      if (ma.property === 'length') {
   328→        // C에는 .length가 없으므로 sizeof 패턴 생성
   329→        return `(sizeof(${obj})/sizeof(${obj}[0]))`;
   330→      }
   331→      return `${obj}.${ma.property}`;
   332→    }
   333→
   334→    return '';
   335→  }
   336→
   337→  /**
   338→   * V 모드 내장 함수 호출 생성
   339→   */
   340→  private genVBuiltinCall(name: string, args: AST.Expression[]): string {
   341→    if (name === 'println') {
   342→      if (args.length === 0) return 'printf("\\n")';
   343→      const firstArg = args[0] as any;
   344→      // StringLiteral인 경우: printf의 format string으로 사용
   345→      if (firstArg.type === 'String') {
   346→        // firstArg.value는 "text" 형태이므로 따옴표 제거
   347→        const str = firstArg.value.slice(1, -1);
   348→        return `printf("${str}\\n")`;
   349→      }
   350→      // 숫자/식별자인 경우 %lld 포맷 사용
   351→      const arg = this.genVExpression(firstArg);
   352→      return `printf("%lld\\n", ${arg})`;
   353→    }
   354→
   355→    if (name === 'print') {
   356→      if (args.length === 0) return 'printf("")';
   357→      const firstArg = args[0] as any;
   358→      if (firstArg.type === 'String') {
   359→        // StringLiteral인 경우: printf의 format string으로 사용
   360→        const str = firstArg.value.slice(1, -1);
   361→        return `printf("${str}")`;
   362→      }
   363→      const arg = this.genVExpression(firstArg);
   364→      return `printf("%lld", ${arg})`;
   365→    }
   366→
   367→    if (name === 'len') {
   368→      const firstArg = args[0] as any;
   369→      if (firstArg.type === 'String') {
   370→        // StringLiteral인 경우 따옴표 제거
   371→        const str = firstArg.value.slice(1, -1);
   372→        return `strlen("${str}")`;
   373→      }
   374→      const arg = this.genVExpression(firstArg);
   375→      return `strlen(${arg})`;
   376→    }
   377→
   378→    if (name === 'to_string') {
   379→      const arg = this.genVExpression(args[0]);
   380→      return arg; // 단순 pass-through
   381→    }
   382→
   383→    if (name === 'int_cast') {
   384→      const firstArg = args[0] as any;
   385→      if (firstArg.type === 'String') {
   386→        const str = firstArg.value.slice(1, -1);
   387→        return `atoi("${str}")`;
   388→      }
   389→      const arg = this.genVExpression(firstArg);
   390→      return `atoi(${arg})`;
   391→    }
   392→
   393→    return '';
   394→  }
   395→
   396→  /**
   397→   * Python 표현식 생성 (Python 코드용)
   398→   */
   399→  private genPyExpression(expr: AST.Expression): string {
   400→    const e = expr as any;
   401→
   402→    if (e.type === 'Number') {
   403→      return (e as AST.NumberLiteral).value.toString();
   404→    }
   405→
   406→    if (e.type === 'String') {
   407→      // StringLiteral.value는 이미 따옴표를 포함 ("text" 형태)
   408→      return (e as AST.StringLiteral).value;
   409→    }
   410→
   411→    if (e.type === 'Identifier') {
   412→      return (e as AST.Identifier).name;
   413→    }
   414→
   415→    if (e.type === 'BinaryExpr') {
   416→      const binExpr = e as AST.BinaryExpr;
   417→      const left = this.genPyExpression(binExpr.left);
   418→      const right = this.genPyExpression(binExpr.right);
   419→      return `${left} ${binExpr.operator} ${right}`;
   420→    }
   421→
   422→    if (e.type === 'Array') {
   423→      const arrayLit = e as AST.ArrayLiteral;
   424→      const elements = arrayLit.elements.map((el) => this.genPyExpression(el)).join(', ');
   425→      return `[${elements}]`;
   426→    }
   427→
   428→    if (e.type === 'ArrayAccess') {
   429→      const arrayAccess = e as AST.ArrayAccess;
   430→      const obj = this.genPyExpression(arrayAccess.object);
   431→      const idx = this.genPyExpression(arrayAccess.index);
   432→      return `${obj}[${idx}]`;
   433→    }
   434→
   435→    if (e.type === 'Call') {
   436→      const callExpr = e as AST.CallExpr;
   437→      const callee = typeof callExpr.callee === 'string' ? callExpr.callee : this.genPyExpression(callExpr.callee);
   438→      const args = callExpr.args.map((arg) => this.genPyExpression(arg)).join(', ');
   439→      return `${callee}(${args})`;
   440→    }
   441→
   442→    if (e.type === 'MemberAccess') {
   443→      const ma = e as AST.MemberAccess;
   444→      const obj = this.genPyExpression(ma.object);
   445→      if (ma.property === 'length') {
   446→        return `len(${obj})`;
   447→      }
   448→      return `${obj}.${ma.property}`;
   449→    }
   450→
   451→    return '';
   452→  }
   453→
   454→  /**
   455→   * V 타입 → C 타입 매핑
   456→   */
   457→  private mapVType(type: string): string {
   458→    const mapping: Record<string, string> = {
   459→      i64: 'long long',
   460→      i32: 'int',
   461→      f64: 'double',
   462→      f32: 'float',
   463→      bool: 'bool',
   464→      string: 'char*',
   465→      void: 'void',
   466→    };
   467→
   468→    return mapping[type] || type;
   469→  }
   470→
   471→  /**
   472→   * Python 타입 → Python 타입 (기본값)
   473→   */
   474→  private mapPyType(type: string): string {
   475→    const mapping: Record<string, string> = {
   476→      i64: 'int',
   477→      i32: 'int',
   478→      f64: 'float',
   479→      f32: 'float',
   480→      bool: 'bool',
   481→      string: 'str',
   482→      void: 'None',
   483→      int: 'int',
   484→      float: 'float',
   485→    };
   486→
   487→    return mapping[type] || type;
   488→  }
   489→
   490→  /**
   491→   * C 코드에 줄 추가
   492→   */
   493→  private writeC(line: string): void {
   494→    this.cLines.push(line);
   495→  }
   496→
   497→  /**
   498→   * Python 코드에 줄 추가
   499→   */
   500→  private writePy(line: string): void {
   501→    this.pyLines.push(line);
   502→  }
   503→
   504→  /**
   505→   * 현재 들여쓰기 문자열
   506→   */
   507→  private indent(): string {
   508→    return '    '.repeat(this.indentLevel);
   509→  }
   510→}
   511→

